                Log("gold2500");
                if (!SpeakLine("BRIBE2_ACCEPTED_THANKS")) { Done(); return; }
                AssassinState = 3; Log("morality"); Log("KILL_SHERIFF");
            } else {
                if (!SpeakLine("BRIBE2_DECLINED")) { Done(); return; }
                AssassinState = 2;
            }
        }
        Done();
    }
};
